D.SpellTexts[188522]={Description={["4b156c7c5e3f6acb:291"]="女伯爵莉娅德琳是第一个血精灵圣骑士。是她最早从纳鲁穆鲁那里偷来了圣光的力量，也是她最早开始为自己的人民寻求宽恕与救赎。一直以来，莉娅德琳凭借着她的力量与信念领导着她的组织。在她看来，血骑士真正的目标只有一个，而且不可动摇——确保彻底消灭燃烧军团。"}}
