D.SpellTexts[243982]={Description={["a1a73dc986a98e3e:452"]="撕裂现实，吸引所有玩家，并对距离裂隙过近的玩家施放引力榨取。\r\n\r\n同时，如果玩家受到了引力榨取的影响，千魂之暗发射的飞弹将被吸引到裂隙之中，而不会击中玩家。\r\n\r\n最后，裂隙还会吸引烈焰宝珠所制造的火焰之池。如果火焰之池接触到接近裂隙的平台边缘，裂隙会吸收火焰，持续地使火焰之池的面积减小。"}}
D.SpellTexts[244856]={Description={["ad56090cb4cdf38d:149"]="在目标位置制造一个烈焰之球，追踪生成时离它最近的玩家。\r\n\r\n当烈焰之球与一名玩家接触时，会触发烈焰爆破。"}}
